(4227484, 609281, 48086, '<td valign="top">Finally a creative entry. Like the colors and the simple light actually works in this setup, my fav so far. The board itself is however slightly skewed, a rotation could fix it. 8</td>', 'Finally a creative entry. Like the colors and the simple light actually works in this setup, my fav so far. The board itself is however slightly skewed, a rotation could fix it. 8', '2007-11-07 05:43:33.000000', NULL, 1),
(4227486, 609549, 48086, '<td valign="top">great idea, but the execution is a bit lacking. The bw conversion looks nice, but the background/table distracts too much. The focus and dof are good. The light is OK but doesnt add to the picture. 7</td>', 'great idea, but the execution is a bit lacking. The bw conversion looks nice, but the background/table distracts too much. The focus and dof are good. The light is OK but doesnt add to the picture. 7', '2007-11-07 05:44:30.000000', NULL, 1),
(4227487, 609899, 48086, '<td valign="top">nice idea, a bit too much oof foreground, a simple crop could fix it, good lighting and use of colors 7</td>', 'nice idea, a bit too much oof foreground, a simple crop could fix it, good lighting and use of colors 7', '2007-11-07 05:44:41.000000', NULL, 1),
(4227489, 609961, 48086, '<td valign="top">with this model and that much popcorn, you should have opted for the classic american beauty shot in the popcorn. about this picture, strange softness, and the black thing on her chest distracts, a bit overexposed on the popcorn.</td>', 'with this model and that much popcorn, you should have opted for the classic american beauty shot in the popcorn. about this picture, strange softness, and the black thing on her chest distracts, a bit overexposed on the popcorn.', '2007-11-07 05:45:53.000000', NULL, 1),
(4227490, 609609, 48086, '<td valign="top">a tighter crop would be better to get rid of the top and right. nice focus and sharpness.</td>', 'a tighter crop would be better to get rid of the top and right. nice focus and sharpness.', '2007-11-07 05:46:12.000000', NULL, 1),
(4227493, 609820, 48086, '<td valign="top">good idea and subject, but the light kills this shot. it now has a yellow haze. also would crop more on the bottom and give more blackness on top for added drama 7</td>', 'good idea and subject, but the light kills this shot. it now has a yellow haze. also would crop more on the bottom and give more blackness on top for added drama 7', '2007-11-07 05:47:14.000000', NULL, 1),
