(4234704, 609820, 58452, '<td valign="top">I bet she doesn''t really like pop corn.</td>', 'I bet she doesn''t really like pop corn.', '2007-11-09 12:37:19.000000', NULL, 1),
(4234706, 608570, 58452, '<td valign="top">Nice balance between the cool blue flame and the warm flying popcorn.</td>', 'Nice balance between the cool blue flame and the warm flying popcorn.', '2007-11-09 12:37:51.000000', NULL, 1),
(4234708, 609880, 79720, '<td valign="top">Wee touch of the camera shakes. If you''re not using a tripod here, you need one. If you are, make sure you set the timer so there''s a lag between the shutter press and the image capture, to let the camera settle.</td>', 'Wee touch of the camera shakes. If you''re not using a tripod here, you need one. If you are, make sure you set the timer so there''s a lag between the shutter press and the image capture, to let the camera settle.', '2007-11-09 12:38:15.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4234712, 609335, 79720, '<td valign="top">I''m having a hard time deciding if I like the reflective surface or not.</td>', 'I''m having a hard time deciding if I like the reflective surface or not.', '2007-11-09 12:39:11.000000', NULL, 1),
(4234713, 609883, 58452, '<td valign="top">Nice simulation.  I like the colors and the grad across the frame.  I wonder why the bottom left kernel is so much darker.</td>', 'Nice simulation.  I like the colors and the grad across the frame.  I wonder why the bottom left kernel is so much darker.', '2007-11-09 12:39:47.000000', NULL, 1),
(4234714, 609204, 79720, '<td valign="top">Ahhh, the precious memories. I light the bokeh (the out of focus region behind your subject), but the child''s hand is underexposed and too centered in the shot. Find a third and crop it there.</td>', 'Ahhh, the precious memories. I light the bokeh (the out of focus region behind your subject), but the child''s hand is underexposed and too centered in the shot. Find a third and crop it there.', '2007-11-09 12:40:37.000000', NULL, 1),
(4234715, 609617, 58452, '<td valign="top">Repeating flash?  Wonder how many tries this took?  Maybe wires holding a series of kernels across the frame?  Nice composition.</td>', 'Repeating flash?  Wonder how many tries this took?  Maybe wires holding a series of kernels across the frame?  Nice composition.', '2007-11-09 12:40:50.000000', NULL, 1),
(4234717, 609504, 58452, '<td valign="top">Nice idea and composition, but the blown thumb distracts just a bit.</td>', 'Nice idea and composition, but the blown thumb distracts just a bit.', '2007-11-09 12:41:43.000000', NULL, 1),
(4234719, 608571, 58452, '<td valign="top">Interesting abstract.  Maybe would work better with one large element closer to focus.</td>', 'Interesting abstract.  Maybe would work better with one large element closer to focus.', '2007-11-09 12:42:28.000000', NULL, 1),
(4234720, 609574, 85155, '<td valign="top">This is a refreshing shot, very unique.  I think the composition is great.  I wish you would have used a higher f-stop though, there is nothing really distracting about the background and almost everything is in focus, you might as well put it all in focus.</td>', 'This is a refreshing shot, very unique.  I think the composition is great.  I wish you would have used a higher f-stop though, there is nothing really distracting about the background and almost everything is in focus, you might as well put it all in focus.', '2007-11-09 12:42:31.000000', NULL, 1),
(4234722, 609938, 79720, '<td valign="top">I like the duotone processing, but the subject is a bit uninteresting.</td>', 'I like the duotone processing, but the subject is a bit uninteresting.', '2007-11-09 12:43:11.000000', NULL, 1),
(4234723, 609387, 79720, '<td valign="top">How Picasso-ish. Doesn''t really do much for me though. :-(</td>', 'How Picasso-ish. Doesn''t really do much for me though. :-(', '2007-11-09 12:43:51.000000', NULL, 1),
(4234725, 609734, 58452, '<td valign="top">Just a little better focus would be nice.</td>', 'Just a little better focus would be nice.', '2007-11-09 12:44:03.000000', NULL, 1),
(4234727, 608249, 79720, '<td valign="top">Very nice post-processing, and a good shallow DoF capture.</td>', 'Very nice post-processing, and a good shallow DoF capture.', '2007-11-09 12:44:23.000000', NULL, 1),
(4234731, 609732, 58452, '<td valign="top">Wonder how you timed the shot?<br/>Be sure to check your lens for oil.  Very hard to clean.</td>', 'Wonder how you timed the shot?Be sure to check your lens for oil.  Very hard to clean.', '2007-11-09 12:45:36.000000', NULL, 1),
(4234733, 608968, 79720, '<td valign="top">This is a bit oversoftened, and that chocolate ball (while I''m sure it''s delicious) looks disgusting. The lighting (on-board flash?) hasn''t really helped. <b>:</b>-(</td>', 'This is a bit oversoftened, and that chocolate ball (while I''m sure it''s delicious) looks disgusting. The lighting (on-board flash?) hasn''t really helped. :-(', '2007-11-09 12:45:52.000000', NULL, 1),
(4234737, 609922, 79720, '<td valign="top">Neat! A bit dark to convey your intention, but nice idea.</td>', 'Neat! A bit dark to convey your intention, but nice idea.', '2007-11-09 12:46:31.000000', NULL, 1),
(4234740, 607614, 58452, '<td valign="top">A continuous background might have been better here, along with a more random arrangement of kernels around the glass.</td>', 'A continuous background might have been better here, along with a more random arrangement of kernels around the glass.', '2007-11-09 12:47:23.000000', NULL, 1),
(4234743, 606928, 58452, '<td valign="top">It took a second look before I saw the continent.  LOL</td>', 'It took a second look before I saw the continent.  LOL', '2007-11-09 12:47:53.000000', NULL, 1),
(4234745, 609574, 58452, '<td valign="top">A trip to the microwave to make the butter half-melt would have greatly helped this image.</td>', 'A trip to the microwave to make the butter half-melt would have greatly helped this image.', '2007-11-09 12:48:45.000000', NULL, 1),
(4234746, 609505, 79720, '<td valign="top">A nice idea, but there seems to be some greyish midtone undercontrast going on. If you play with level adjustment layers in Photoshop, move that midpoint grey slider to the right to increase the midtone contrast slightly.</td>', 'A nice idea, but there seems to be some greyish midtone undercontrast going on. If you play with level adjustment layers in Photoshop, move that midpoint grey slider to the right to increase the midtone contrast slightly.', '2007-11-09 12:48:52.000000', NULL, 1),
(4234749, 608045, 58452, '<td valign="top">Ungh.  Burnt popcorn leaves a bad taste.</td>', 'Ungh.  Burnt popcorn leaves a bad taste.', '2007-11-09 12:49:18.000000', NULL, 1),
(4234750, 609895, 79720, '<td valign="top">Nice action capture. Hope you didn''t get any oil on your lens.</td>', 'Nice action capture. Hope you didn''t get any oil on your lens.', '2007-11-09 12:49:29.000000', NULL, 1),
(4234751, 608159, 58452, '<td valign="top">Wow, what a weird perspective on baby! A crop from a wide angle?  Seems happy and cute!</td>', 'Wow, what a weird perspective on baby! A crop from a wide angle?  Seems happy and cute!', '2007-11-09 12:50:36.000000', NULL, 1),
(4234753, 609871, 58452, '<td valign="top">The top kernels seem just a bit overexposed to me.  Hard to photograph mostly light tones.  Could help to use manual mode on the camer.</td>', 'The top kernels seem just a bit overexposed to me.  Hard to photograph mostly light tones.  Could help to use manual mode on the camer.', '2007-11-09 12:51:27.000000', NULL, 1),
(4234758, 609952, 85155, '<td valign="top">Where''s the popcorn? You could have at least shown some popcorn sprinkled on the movies.  I also think that you need to make everything in focus, try setting your f-stop higher.  I do like the diagonal lines, this angle is nice.</td>', 'Where''s the popcorn? You could have at least shown some popcorn sprinkled on the movies.  I also think that you need to make everything in focus, try setting your f-stop higher.  I do like the diagonal lines, this angle is nice.', '2007-11-09 12:53:50.000000', NULL, 1),
(4234762, 608842, 79720, '<td valign="top">The highlights on the kernels seem a little blownout. Was it natural light?</td>', 'The highlights on the kernels seem a little blownout. Was it natural light?', '2007-11-09 12:54:51.000000', NULL, 1),
(4234763, 609940, 85155, '<td valign="top">Too much white here, it kind of feels like everything is blown out.  Try the same thing on a black background.  Also see what it looks like if the progression is moving diagonally across the frame, rather than right in the middle moving straight up.</td>', 'Too much white here, it kind of feels like everything is blown out.  Try the same thing on a black background.  Also see what it looks like if the progression is moving diagonally across the frame, rather than right in the middle moving straight up.', '2007-11-09 12:54:58.000000', NULL, 1),
(4234765, 609617, 79720, '<td valign="top">That seems like a lot of work in the setup. Props for that.</td>', 'That seems like a lot of work in the setup. Props for that.', '2007-11-09 12:55:34.000000', NULL, 1),
(4234767, 609246, 79720, '<td valign="top">Spooky monochrome, almost abstract-ish.</td>', 'Spooky monochrome, almost abstract-ish.', '2007-11-09 12:55:57.000000', NULL, 1),
(4234772, 609719, 85155, '<td valign="top">I really like the reflection here.  It is just a tad to dark for me, I would like to see how it compares to being a little lighter.  Also try not to have the "horizon", where the popcorn is sitting on the table, be right in the middle, think rule of thirds.  Also I don''t know if this is on purpose but straightening out that line between the popcorn and the table would make this shot better too.</td>', 'I really like the reflection here.  It is just a tad to dark for me, I would like to see how it compares to being a little lighter.  Also try not to have the "horizon", where the popcorn is sitting on the table, be right in the middle, think rule of thirds.  Also I don''t know if this is on purpose but straightening out that line between the popcorn and the table would make this shot better too.', '2007-11-09 12:57:06.000000', NULL, 1),
(4234773, 609952, 79720, '<td valign="top">An interesting take.</td>', 'An interesting take.', '2007-11-09 12:57:20.000000', NULL, 1),
(4234777, 609281, 79720, '<td valign="top">Well, Im 47% through voting, and this is the first one that begs for something more than average. I''ll call a top 10, at least.</td>', 'Well, Im 47% through voting, and this is the first one that begs for something more than average. I''ll call a top 10, at least.', '2007-11-09 12:58:32.000000', NULL, 1),
(4234780, 609657, 85155, '<td valign="top">This shot is too symmetrical, it takes out the interest in the shot.  Try taking it on an angle instead of straight on, or move the kernels to a third instead of right in the middle.  The composition is just lacking interest.</td>', 'This shot is too symmetrical, it takes out the interest in the shot.  Try taking it on an angle instead of straight on, or move the kernels to a third instead of right in the middle.  The composition is just lacking interest.', '2007-11-09 12:59:02.000000', NULL, 1),
(4234781, 609961, 79720, '<td valign="top">A bit too much softening for me, but hottie!</td>', 'A bit too much softening for me, but hottie!', '2007-11-09 12:59:10.000000', NULL, 1),
(4234783, 609898, 79720, '<td valign="top">On board flash? It created a few distracting shadows.<br/> <br/>edit: Spelling. <b>:</b>-(<br/><br/><i>Message edited by author 2007-11-14 07:44:40.</i></td>', 'On board flash? It created a few distracting shadows. edit: Spelling. :-(', '2007-11-09 12:59:53.000000', '2007-11-14 07:44:40.000000', 1),
(4234788, 609610, 58452, '<td valign="top">If you''d move your model a bit away from the wall those hard shadows would disappear.</td>', 'If you''d move your model a bit away from the wall those hard shadows would disappear.', '2007-11-09 13:01:20.000000', NULL, 1),
(4234793, 606874, 85155, '<td valign="top">What was your iso on this shot?  It looks like there is a lot of noise.  This is a stretch to meet the challenge, there are so many good, unique, interesting ideas so far, and this looks like it took no effort.</td>', 'What was your iso on this shot?  It looks like there is a lot of noise.  This is a stretch to meet the challenge, there are so many good, unique, interesting ideas so far, and this looks like it took no effort.', '2007-11-09 13:02:07.000000', NULL, 1),
(4234794, 608159, 79720, '<td valign="top">Very cute, but watch your ratio when you resize. This image looks horizontally squashed.</td>', 'Very cute, but watch your ratio when you resize. This image looks horizontally squashed.', '2007-11-09 13:02:15.000000', NULL, 1),
(4234796, 609188, 58452, '<td valign="top">Love the positioning of the gun in the composition.</td>', 'Love the positioning of the gun in the composition.', '2007-11-09 13:02:49.000000', NULL, 1),
(4234797, 609504, 85155, '<td valign="top">This is along the lines of my first thoughts when I saw the challenge.  I have just been waiting to see something like it.  Nicely done.</td>', 'This is along the lines of my first thoughts when I saw the challenge.  I have just been waiting to see something like it.  Nicely done.', '2007-11-09 13:02:52.000000', NULL, 1),
(4234799, 609961, 85155, '<td valign="top">Tasteless!</td>', 'Tasteless!', '2007-11-09 13:03:24.000000', NULL, 1),
(4234811, 608656, 58452, '<td valign="top">Nice perspective.</td>', 'Nice perspective.', '2007-11-09 13:09:07.000000', NULL, 1),
(4234816, 609431, 85155, '<td valign="top">This is a very unique idea, nice thought for the challenge.  On my monitor the colors look a little dull, this could definitely use some help from a levels adjustment.  Try to work on the colors to bring it more to life.  I spy...a key.</td>', 'This is a very unique idea, nice thought for the challenge.  On my monitor the colors look a little dull, this could definitely use some help from a levels adjustment.  Try to work on the colors to bring it more to life.  I spy...a key.', '2007-11-09 13:10:21.000000', NULL, 1),
(4234820, 609466, 58452, '<td valign="top">Nice colors.</td>', 'Nice colors.', '2007-11-09 13:12:51.000000', NULL, 1),
(4234822, 609922, 58452, '<td valign="top">Very creative.</td>', 'Very creative.', '2007-11-09 13:13:10.000000', NULL, 1),
(4234824, 609719, 58452, '<td valign="top">A tad underexposed for my taste.</td>', 'A tad underexposed for my taste.', '2007-11-09 13:14:22.000000', NULL, 1),
(4234831, 608968, 58452, '<td valign="top">Eeewwie!  Messy!  LOL  Maybe a touch of overexposure on the face.</td>', 'Eeewwie!  Messy!  LOL  Maybe a touch of overexposure on the face.', '2007-11-09 13:18:12.000000', NULL, 1),
(4234845, 608249, 86365, '<td valign="top">I love this! I always wanted a popcorn tree. The lighting is great- it is a different take on popcorn.</td>', 'I love this! I always wanted a popcorn tree. The lighting is great- it is a different take on popcorn.', '2007-11-09 13:24:51.000000', NULL, 1),
(4234847, 609776, 58452, '<td valign="top">Seems just a bit underexposed to me.</td>', 'Seems just a bit underexposed to me.', '2007-11-09 13:25:55.000000', NULL, 1),
(4234848, 608570, 86365, '<td valign="top">This is really cool- the popcorn really stands out, everything works really well together in this image.</td>', 'This is really cool- the popcorn really stands out, everything works really well together in this image.', '2007-11-09 13:26:14.000000', NULL, 1),
(4234851, 606874, 58452, '<td valign="top">Nice texture on the buds.  Purple popcorn?  LOL</td>', 'Nice texture on the buds.  Purple popcorn?  LOL', '2007-11-09 13:27:46.000000', NULL, 1),
(4234914, 608439, 79720, '<td valign="top">What an adorable image. The comforter even looks like popcorn!</td>', 'What an adorable image. The comforter even looks like popcorn!', '2007-11-09 13:59:27.000000', NULL, 1),
(4234916, 609946, 79720, '<td valign="top">This munchkin gets around, eh? What a ham.</td>', 'This munchkin gets around, eh? What a ham.', '2007-11-09 14:00:19.000000', NULL, 1),
(4234917, 607598, 79720, '<td valign="top">Priceless.</td>', 'Priceless.', '2007-11-09 14:00:31.000000', NULL, 1),
(4234918, 609899, 79720, '<td valign="top">Somehow, I don''t think the Media Wizards of Madison Ave. were behind this image...but I bet I know who was. We shall see.</td>', 'Somehow, I don''t think the Media Wizards of Madison Ave. were behind this image...but I bet I know who was. We shall see.', '2007-11-09 14:01:48.000000', NULL, 1),
(4234991, 609431, 85797, '<td valign="top">This would be a really nice photo except that there isn''t enough popcorn in the photo. The other elements in the photo tend to distract from the popcorn; otherwise, this is a nice, sharp photo.</td>', 'This would be a really nice photo except that there isn''t enough popcorn in the photo. The other elements in the photo tend to distract from the popcorn; otherwise, this is a nice, sharp photo.', '2007-11-09 14:45:07.000000', NULL, 1),
(4234992, 606874, 85797, '<td valign="top">Topic is "popcorn" not flowers.</td>', 'Topic is "popcorn" not flowers.', '2007-11-09 14:46:35.000000', NULL, 1),
(4234994, 609287, 85797, '<td valign="top">Nice photo except the "rule of thirds" was not applied to the dog and popcorn.</td>', 'Nice photo except the "rule of thirds" was not applied to the dog and popcorn.', '2007-11-09 14:47:47.000000', NULL, 1),
(4234998, 609788, 85797, '<td valign="top">Nice photo. Black background really allows the dog, popcorn and bowl to truly show their color.</td>', 'Nice photo. Black background really allows the dog, popcorn and bowl to truly show their color.', '2007-11-09 14:49:00.000000', NULL, 1),
(4235000, 606928, 85797, '<td valign="top">Nice coloring, textured background. Looks like just a bit of camera shake when looking towards the back of the photo.</td>', 'Nice coloring, textured background. Looks like just a bit of camera shake when looking towards the back of the photo.', '2007-11-09 14:51:15.000000', NULL, 1),
(4235004, 608159, 85797, '<td valign="top">Baby''s face looks like the photo was resized too, too much. Cute photo although it the child had popcorn in it lap it would have carried over to the popcorn on the floor. Nice eye glint!</td>', 'Baby''s face looks like the photo was resized too, too much. Cute photo although it the child had popcorn in it lap it would have carried over to the popcorn on the floor. Nice eye glint!', '2007-11-09 14:53:11.000000', NULL, 1),
(4235005, 609387, 85797, '<td valign="top">Does not meet the challenge "popcorn."</td>', 'Does not meet the challenge "popcorn."', '2007-11-09 14:54:25.000000', NULL, 1),
(4235011, 608045, 85797, '<td valign="top">Nice job on photo but the title could have been more appropriate.</td>', 'Nice job on photo but the title could have been more appropriate.', '2007-11-09 14:55:15.000000', NULL, 1),
(4235017, 609776, 85797, '<td valign="top">Really nice black and white photo. Several shadows, textured background, and different era types of popcorn methods.</td>', 'Really nice black and white photo. Several shadows, textured background, and different era types of popcorn methods.', '2007-11-09 14:57:07.000000', NULL, 1),
(4235021, 608607, 85797, '<td valign="top">Nice sharp photo. Little geisha is interested in birds as they are her throwing the popcorn.</td>', 'Nice sharp photo. Little geisha is interested in birds as they are her throwing the popcorn.', '2007-11-09 14:59:01.000000', NULL, 1),
(4235025, 609952, 85797, '<td valign="top">Does not meet the challenge "popcorn."</td>', 'Does not meet the challenge "popcorn."', '2007-11-09 14:59:44.000000', NULL, 1),
(4235026, 609466, 85797, '<td valign="top">Nice and sharp photo. Great idea!</td>', 'Nice and sharp photo. Great idea!', '2007-11-09 15:00:14.000000', NULL, 1),
(4235028, 609574, 85797, '<td valign="top">Great photo!</td>', 'Great photo!', '2007-11-09 15:01:20.000000', NULL, 1),
(4235032, 609411, 85797, '<td valign="top">Great photo!</td>', 'Great photo!', '2007-11-09 15:02:22.000000', NULL, 1),
(4235035, 608383, 85797, '<td valign="top">Creative, popcorn stands out while the background is blurred.</td>', 'Creative, popcorn stands out while the background is blurred.', '2007-11-09 15:03:06.000000', NULL, 1),
(4235038, 608816, 85797, '<td valign="top">Photo could be a bit sharper since the intent is to include the bowl of popcorn as well. Blurring the remainder is great.</td>', 'Photo could be a bit sharper since the intent is to include the bowl of popcorn as well. Blurring the remainder is great.', '2007-11-09 15:04:48.000000', NULL, 1),
(4235043, 608570, 85797, '<td valign="top">Nice photo!</td>', 'Nice photo!', '2007-11-09 15:07:34.000000', NULL, 1),
(4235049, 609335, 85797, '<td valign="top">Nice reflections, good choice of background.</td>', 'Nice reflections, good choice of background.', '2007-11-09 15:08:13.000000', NULL, 1),
(4235052, 609364, 85797, '<td valign="top">Doesn''t meet challenge theme!</td>', 'Doesn''t meet challenge theme!', '2007-11-09 15:08:55.000000', NULL, 1),
(4235056, 609940, 85797, '<td valign="top">Would have been a great photo if the background was some other color than white so that the other colors would show up more abundantly.</td>', 'Would have been a great photo if the background was some other color than white so that the other colors would show up more abundantly.', '2007-11-09 15:10:06.000000', NULL, 1),
(4235070, 609818, 85797, '<td valign="top">Not appropriate to challenge them!</td>', 'Not appropriate to challenge them!', '2007-11-09 15:14:00.000000', NULL, 1),
(4235074, 608465, 85797, '<td valign="top">Great photo. Dog has eye glint. Blurred background. Focus on dog and popcorn!</td>', 'Great photo. Dog has eye glint. Blurred background. Focus on dog and popcorn!', '2007-11-09 15:15:54.000000', NULL, 1),
(4235081, 609609, 85797, '<td valign="top">Beautiful photo but not challenge them!</td>', 'Beautiful photo but not challenge them!', '2007-11-09 15:17:48.000000', NULL, 1),
(4235085, 609617, 85797, '<td valign="top">Creative idea.</td>', 'Creative idea.', '2007-11-09 15:18:28.000000', NULL, 1),
(4235089, 609818, 3746, '<td valign="top">LOL - this is truly truly awful, I don''t think I have ever seen such a shoe-horned image in all my time here at DPC.. its laughably bad. sorry.</td>', 'LOL - this is truly truly awful, I don''t think I have ever seen such a shoe-horned image in all my time here at DPC.. its laughably bad. sorry.', '2007-11-09 15:20:09.000000', NULL, 1),
(4235100, 609549, 3746, '<td valign="top">a good idea you could of done so much more with - a massively missed opportunity.</td>', 'a good idea you could of done so much more with - a massively missed opportunity.', '2007-11-09 15:23:06.000000', NULL, 1),
(4235131, 606874, 42254, '<td valign="top">Lovely flowers, but I only see a remote analogy to popcorn.</td>', 'Lovely flowers, but I only see a remote analogy to popcorn.', '2007-11-09 15:39:43.000000', NULL, 1),
(4235134, 608383, 42254, '<td valign="top">Beautiful shot of a rare flower!!</td>', 'Beautiful shot of a rare flower!!', '2007-11-09 15:41:00.000000', NULL, 1),
(4235139, 609732, 42254, '<td valign="top">Seems to be too blurry...perhaps with more kernels some could be stopped &amp; in focus; hard to see that these are popcorn kernels.</td>', 'Seems to be too blurry...perhaps with more kernels some could be stopped & in focus; hard to see that these are popcorn kernels.', '2007-11-09 15:42:28.000000', NULL, 1),
(4235140, 609364, 42254, '<td valign="top">Looks like a kernel!</td>', 'Looks like a kernel!', '2007-11-09 15:43:21.000000', NULL, 1),
(4235141, 609287, 42254, '<td valign="top">Popcorn is overexposed and costrast is flat, but nice idea and beautiful dog.</td>', 'Popcorn is overexposed and costrast is flat, but nice idea and beautiful dog.', '2007-11-09 15:44:18.000000', NULL, 1),
(4235144, 609864, 42254, '<td valign="top">Good job of catching the corn in-air; nice use of black pot &amp; background for contrast with the white corn.</td>', 'Good job of catching the corn in-air; nice use of black pot & background for contrast with the white corn.', '2007-11-09 15:45:24.000000', NULL, 1),
(4235151, 609505, 42254, '<td valign="top">Clever to shape a popcorn cob &amp; to use the movie tickets in the husks!  Nice colors as well.</td>', 'Clever to shape a popcorn cob & to use the movie tickets in the husks!  Nice colors as well.', '2007-11-09 15:47:02.000000', NULL, 1),
(4235159, 609922, 42254, '<td valign="top">Clever; I''ll be anxious to read how you got the yellow streaks without setting the kernels on fire! Nice composition and contrast with black background.</td>', 'Clever; I''ll be anxious to read how you got the yellow streaks without setting the kernels on fire! Nice composition and contrast with black background.', '2007-11-09 15:48:44.000000', NULL, 1),
(4235161, 609504, 42254, '<td valign="top">The slow way!  Clever idea well implemented.</td>', 'The slow way!  Clever idea well implemented.', '2007-11-09 15:49:11.000000', NULL, 1),
(4235165, 608607, 42254, '<td valign="top">Beautiful colors &amp; nice shot.</td>', 'Beautiful colors & nice shot.', '2007-11-09 15:50:14.000000', NULL, 1),
(4235167, 608465, 42254, '<td valign="top">Great shot of those expressive eyes!</td>', 'Great shot of those expressive eyes!', '2007-11-09 15:51:34.000000', NULL, 1),
