(4237954, 609281, 73452, '<td valign="top">is this by Sherpet?  it looks like something she''d do.  anyways, great job, i love the different colors, only distraction is the shadows.</td>', 'is this by Sherpet?  it looks like something she''d do.  anyways, great job, i love the different colors, only distraction is the shadows.', '2007-11-10 23:03:21.000000', NULL, 1),
(4237962, 607598, 73452, '<td valign="top">Aha, im expecting a ribbon with this, very cute kid, and i love all the popcorn!  Great job!</td>', 'Aha, im expecting a ribbon with this, very cute kid, and i love all the popcorn!  Great job!', '2007-11-10 23:07:03.000000', NULL, 1),
(4237966, 609871, 73452, '<td valign="top">way blown out.</td>', 'way blown out.', '2007-11-10 23:08:25.000000', NULL, 1),
