(4238187, 609549, 30490, '<td valign="top">Love it!  Great idea and lovely b/w shot!  Best in challenge for me!  10</td>', 'Love it!  Great idea and lovely b/w shot!  Best in challenge for me!  10', '2007-11-11 02:36:01.000000', NULL, 1),
