(4238906, 608816, 61073, '<td valign="top">May have been better with more of the front popcorn in focus..</td>', 'May have been better with more of the front popcorn in focus..', '2007-11-11 18:33:29.000000', NULL, 1),
(4238908, 609952, 61073, '<td valign="top">May be ok if the challenge were Movies...</td>', 'May be ok if the challenge were Movies...', '2007-11-11 18:34:49.000000', NULL, 1),
