INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4239029, 609818, 74953, '<td valign="top">Decent picture, but only meets requirements by title.</td>', 'Decent picture, but only meets requirements by title.', '2007-11-11 19:58:16.000000', NULL, 1),
(4239038, 609961, 76198, '<td valign="top">That''s a lot of popcorn... Nice "glamor" look; the skin is a little <i>too</i> smooth for my tastes but that''s just tastes.</td>', 'That''s a lot of popcorn... Nice "glamor" look; the skin is a little too smooth for my tastes but that''s just tastes.', '2007-11-11 20:01:57.000000', NULL, 1),
(4239043, 609204, 76198, '<td valign="top">This image has a number of things that detract from it, IMO - it''s compositionally not very interesting (centered subject), focus is a bit soft, and really needs some post-processing as it''s a bit dark and "flat."</td>', 'This image has a number of things that detract from it, IMO - it''s compositionally not very interesting (centered subject), focus is a bit soft, and really needs some post-processing as it''s a bit dark and "flat."', '2007-11-11 20:04:01.000000', NULL, 1),
(4239048, 609820, 76198, '<td valign="top">Wonderful.</td>', 'Wonderful.', '2007-11-11 20:07:20.000000', NULL, 1),
(4239050, 609281, 76198, '<td valign="top">By far the best I''ve seen yet.</td>', 'By far the best I''ve seen yet.', '2007-11-11 20:08:12.000000', NULL, 1),
(4239054, 609617, 76198, '<td valign="top">This must have taken forever to get right!</td>', 'This must have taken forever to get right!', '2007-11-11 20:11:33.000000', NULL, 1),
