(4239064, 609574, 76198, '<td valign="top">Great concept; color has a slight yellowish hue on my screen.</td>', 'Great concept; color has a slight yellowish hue on my screen.', '2007-11-11 20:16:52.000000', NULL, 1),
(4239068, 609364, 76198, '<td valign="top">Too much of a stretch for me...</td>', 'Too much of a stretch for me...', '2007-11-11 20:17:27.000000', NULL, 1),
