(4239082, 609899, 76198, '<td valign="top">My first 10. He''s a beaut.</td>', 'My first 10. He''s a beaut.', '2007-11-11 20:21:32.000000', NULL, 1),
(4239090, 608860, 67697, '<td valign="top">Very funny!  Love the spilled butter.</td>', 'Very funny!  Love the spilled butter.', '2007-11-11 20:28:35.000000', NULL, 1),
