(4239247, 609335, 2134, '<td valign="top">I like the reflections...nice compositon.</td>', 'I like the reflections...nice compositon.', '2007-11-11 21:54:45.000000', NULL, 1),
(4239253, 609852, 2134, '<td valign="top">Nice concept, the popcorn machine is a little distracting to me.  I think that the popcorn and the coke by itself would have made a better shot.</td>', 'Nice concept, the popcorn machine is a little distracting to me.  I think that the popcorn and the coke by itself would have made a better shot.', '2007-11-11 21:56:03.000000', NULL, 1),
