(4239291, 608570, 2134, '<td valign="top">Nice shot... the blue burner and the yellow popcorn against the black background, very creative.</td>', 'Nice shot... the blue burner and the yellow popcorn against the black background, very creative.', '2007-11-11 22:07:05.000000', NULL, 1),
