(4241322, 609776, 68454, '<td valign="top">They still make Jiffy Pop?  Overall, this looks very gray to me.  Nice blacks, but the whites are a bit dull.  Perhaps a levels adjustment would have helped.</td>', 'They still make Jiffy Pop?  Overall, this looks very gray to me.  Nice blacks, but the whites are a bit dull.  Perhaps a levels adjustment would have helped.', '2007-11-12 13:43:39.000000', NULL, 1),
(4241477, 609635, 811, '<td valign="top">I think a tighter crop and a bit sharper focus would have really made this shot.  As it is, all teh extra "non-popcorned" space and the wall outlet are a bit distracting.</td>', 'I think a tighter crop and a bit sharper focus would have really made this shot.  As it is, all teh extra "non-popcorned" space and the wall outlet are a bit distracting.', '2007-11-12 14:58:07.000000', NULL, 1),
(4241486, 609610, 811, '<td valign="top">Very interesting idea, but I think you have included too much "stuff" to be completely effective.  Also, the shadow is very distracting.  For some reason, the bottle and flower''s shadow grabs my eye.</td>', 'Very interesting idea, but I think you have included too much "stuff" to be completely effective.  Also, the shadow is very distracting.  For some reason, the bottle and flower''s shadow grabs my eye.', '2007-11-12 15:01:40.000000', NULL, 1),
(4241489, 609411, 811, '<td valign="top">The crop feels a bit odd on this.  I think either making it broader and more inclusive or tighter would be a bit better.</td>', 'The crop feels a bit odd on this.  I think either making it broader and more inclusive or tighter would be a bit better.', '2007-11-12 15:04:42.000000', NULL, 1),
